package ae.book;

import static org.junit.jupiter.api.Assertions.*;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.TreeMap;
import org.junit.jupiter.api.Test;

/** One hand-built corrupt structure per rule of {@link OrderBook#checkInvariants()}; reflection builds the corruption. */
class InvariantCheckerTest {

    private static Object get(Object target, String field) throws ReflectiveOperationException {
        Field f = target.getClass().getDeclaredField(field);
        f.setAccessible(true);
        return f.get(target);
    }

    private static void set(Object target, String field, Object value) throws ReflectiveOperationException {
        Field f = target.getClass().getDeclaredField(field);
        f.setAccessible(true);
        f.set(target, value);
    }

    @SuppressWarnings("unchecked")
    private static Map<Long, Object> byId(OrderBook b) throws ReflectiveOperationException {
        return (Map<Long, Object>) get(b, "byId");
    }

    @SuppressWarnings("unchecked")
    private static TreeMap<Long, LinkedHashMap<Long, Object>> side(OrderBook b, String name) throws ReflectiveOperationException {
        return (TreeMap<Long, LinkedHashMap<Long, Object>>) get(b, name);
    }

    private static String message(OrderBook b) {
        return assertThrows(IllegalStateException.class, b::checkInvariants).getMessage();
    }

    private static OrderBook oneBid(long display) {
        OrderBook b = new OrderBook();
        b.submit(Limit.of(1, "a", Side.BUY, 100, 10).iceberg(display));
        b.checkInvariants(); // control: the uncorrupted book is valid
        return b;
    }

    @Test
    void healthyBookPasses() {
        OrderBook b = oneBid(3);
        b.submit(Limit.of(2, "b", Side.SELL, 101, 4));
        b.checkInvariants();
    }

    @Test
    void emptyLevelDetected() throws Exception {
        OrderBook b = oneBid(0);
        side(b, "bids").put(90L, new LinkedHashMap<>());
        assertTrue(message(b).startsWith("empty level 90"), message(b));
    }

    @Test
    void misfiledOrderDetected() throws Exception {
        OrderBook b = oneBid(0);
        Object r = byId(b).get(1L);
        set(r, "total", 10L);
        LinkedHashMap<Long, Object> level = side(b, "bids").remove(100L);
        side(b, "bids").put(95L, level); // order says price 100 but sits at 95
        assertTrue(message(b).startsWith("misfiled 1"), message(b));
    }

    @Test
    void keyIdMismatchDetected() throws Exception {
        OrderBook b = oneBid(0);
        Object r = byId(b).get(1L);
        LinkedHashMap<Long, Object> level = side(b, "bids").get(100L);
        level.remove(1L);
        level.put(7L, r);
        assertTrue(message(b).startsWith("key/id mismatch 1"), message(b));
    }

    @Test
    void indexMismatchDetected() throws Exception {
        OrderBook b = oneBid(0);
        byId(b).remove(1L);
        assertTrue(message(b).startsWith("index mismatch 1"), message(b));
    }

    @Test
    void indexSizeDetected() throws Exception {
        OrderBook b = oneBid(0);
        byId(b).put(999L, byId(b).get(1L)); // extra index entry, per-order checks still pass
        assertTrue(message(b).startsWith("index size 2 vs 1"), message(b));
    }

    @Test
    void nonPositiveTotalDetected() throws Exception {
        OrderBook b = oneBid(0);
        set(byId(b).get(1L), "total", 0L);
        assertTrue(message(b).startsWith("non-positive total 1"), message(b));
    }

    @Test
    void visibleAboveTotalDetected() throws Exception {
        OrderBook b = oneBid(0);
        set(byId(b).get(1L), "visible", 11L);
        assertTrue(message(b).startsWith("bad visible 1"), message(b));
    }

    @Test
    void zeroVisibleDetected() throws Exception {
        OrderBook b = oneBid(3);
        set(byId(b).get(1L), "visible", 0L);
        assertTrue(message(b).startsWith("bad visible 1"), message(b));
    }

    @Test
    void plainOrderHidingQuantityDetected() throws Exception {
        OrderBook b = oneBid(0);
        set(byId(b).get(1L), "visible", 4L);
        assertTrue(message(b).startsWith("hidden plain 1"), message(b));
    }

    @Test
    void visibleOverDisplayDetected() throws Exception {
        OrderBook b = oneBid(3);
        set(byId(b).get(1L), "visible", 5L);
        assertTrue(message(b).startsWith("over display 1"), message(b));
    }

    @Test
    void crossedBookDetected() throws Exception {
        OrderBook b = oneBid(0);
        OrderBook other = new OrderBook();
        other.submit(Limit.of(50, "x", Side.SELL, 100, 2)); // equal price counts as crossed
        Object foreign = byId(other).get(50L);
        side(b, "asks").computeIfAbsent(100L, p -> new LinkedHashMap<>()).put(50L, foreign);
        byId(b).put(50L, foreign);
        assertTrue(message(b).startsWith("crossed book 100 >= 100"), message(b));
    }

    @Test
    void touchingButNotCrossedBookPasses() throws Exception {
        OrderBook b = oneBid(0);
        OrderBook other = new OrderBook();
        other.submit(Limit.of(50, "x", Side.SELL, 101, 2));
        Object foreign = byId(other).get(50L);
        side(b, "asks").computeIfAbsent(101L, p -> new LinkedHashMap<>()).put(50L, foreign);
        byId(b).put(50L, foreign);
        b.checkInvariants();
    }

    @Test
    void reflectionHelperSanity() throws Exception {
        // the corruption helpers can find the private class constructor shape (guards against silent no-op tests)
        Class<?> c = Class.forName("ae.book.OrderBook$Resting");
        Constructor<?>[] ctors = c.getDeclaredConstructors();
        assertEquals(1, ctors.length);
        assertEquals(6, ctors[0].getParameterCount());
    }
}

package ae.book;

import static org.junit.jupiter.api.Assertions.*;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import java.util.Random;
import org.junit.jupiter.api.Test;

/**
 * Differential test: the production book against a naive oracle that keeps one flat list and re-sorts on every match.
 */
class OracleDifferentialTest {

    /** Independent reference model; shares only the public value types with the production code. */
    static final class Oracle {
        static final class Ord {
            long id; String owner; Side side; long price; long total; long visible; long display; long seq;
        }

        final List<Ord> orders = new ArrayList<>();
        long seq = 0;

        Optional<Ord> find(long id) {
            return orders.stream().filter(o -> o.id == id).findFirst();
        }

        boolean crosses(Side takerSide, Long limit, long makerPrice) {
            if (limit == null) return true;
            return takerSide == Side.BUY ? makerPrice <= limit : makerPrice >= limit;
        }

        Comparator<Ord> matchOrder(Side makerSide) {
            Comparator<Ord> byPrice = makerSide == Side.SELL
                    ? Comparator.comparingLong(o -> o.price)
                    : Comparator.comparingLong((Ord o) -> o.price).reversed();
            return byPrice.thenComparingLong(o -> o.seq);
        }

        Result run(long id, String owner, Side side, Long limit, long qty, Tif tif, boolean post, long display,
                   boolean market) {
            List<Ord> opp = new ArrayList<>(orders.stream().filter(o -> o.side != side && crosses(side, limit, o.price)).toList());
            opp.sort(matchOrder(side.opposite()));
            if (post && !opp.isEmpty()) return new Result(Status.REJECTED, List.of(), 0, qty, "POST_ONLY");
            if (tif == Tif.FOK && !fok(opp, owner, qty)) return new Result(Status.REJECTED, List.of(), 0, qty, "FOK");
            List<Trade> trades = new ArrayList<>();
            long rem = qty;
            boolean stp = false;
            while (rem > 0) {
                List<Ord> cand = new ArrayList<>(orders.stream()
                        .filter(o -> o.side != side && crosses(side, limit, o.price)).toList());
                if (cand.isEmpty()) break;
                cand.sort(matchOrder(side.opposite()));
                Ord m = cand.get(0);
                if (m.owner.equals(owner)) { stp = true; break; }
                long q = Math.min(rem, m.visible);
                trades.add(new Trade(id, m.id, m.price, q));
                rem -= q; m.total -= q; m.visible -= q;
                if (m.total == 0) orders.remove(m);
                else if (m.visible == 0) { m.visible = Math.min(m.display, m.total); m.seq = seq++; }
            }
            long filled = qty - rem;
            if (rem == 0) return new Result(Status.FILLED, trades, filled, 0, "");
            if (stp) return new Result(Status.CANCELLED, trades, filled, rem, "SELF_TRADE");
            if (market) return new Result(Status.CANCELLED, trades, filled, rem, "MARKET");
            if (tif == Tif.IOC) return new Result(Status.CANCELLED, trades, filled, rem, "IOC");
            Ord o = new Ord();
            o.id = id; o.owner = owner; o.side = side; o.price = limit; o.total = rem; o.display = display;
            o.visible = display > 0 ? Math.min(display, rem) : rem; o.seq = seq++;
            orders.add(o);
            return new Result(Status.RESTING, trades, filled, rem, "");
        }

        boolean fok(List<Ord> sortedCrossing, String owner, long qty) {
            long cum = 0;
            List<Long> prices = sortedCrossing.stream().map(o -> o.price).distinct().toList();
            for (long p : prices) {
                List<Ord> level = sortedCrossing.stream().filter(o -> o.price == p).toList();
                if (level.stream().anyMatch(o -> o.owner.equals(owner))) return cum >= qty;
                cum += level.stream().mapToLong(o -> o.total).sum();
                if (cum >= qty) return true;
            }
            return cum >= qty;
        }

        boolean cancel(long id) {
            return orders.removeIf(o -> o.id == id);
        }

        boolean amend(long id, long n) {
            Optional<Ord> f = find(id);
            if (f.isEmpty()) return false;
            Ord o = f.get();
            if (n < o.total) { o.total = n; o.visible = Math.min(o.visible, n); }
            else if (n > o.total) {
                o.total = n; o.visible = o.display > 0 ? Math.min(o.display, n) : n; o.seq = seq++;
            }
            return true;
        }

        Result replace(long id, long p, long q) {
            Ord o = find(id).orElseThrow();
            orders.remove(o);
            return run(id, o.owner, o.side, p, q, Tif.GTC, false, o.display, false);
        }

        List<Level> depth(Side side) {
            List<Ord> side0 = new ArrayList<>(orders.stream().filter(o -> o.side == side).toList());
            side0.sort(matchOrder(side));
            List<Level> out = new ArrayList<>();
            for (Ord o : side0) {
                if (!out.isEmpty() && out.get(out.size() - 1).price() == o.price) {
                    Level l = out.remove(out.size() - 1);
                    out.add(new Level(l.price(), l.visibleQty() + o.visible, l.orders() + 1));
                } else {
                    out.add(new Level(o.price, o.visible, 1));
                }
            }
            return out;
        }
    }

    private static void runSeed(long seed, int steps, int owners, int priceSpan) {
        Random rnd = new Random(seed);
        OrderBook book = new OrderBook();
        Oracle oracle = new Oracle();
        long nextId = 1;
        List<Long> everUsed = new ArrayList<>();
        for (int step = 0; step < steps; step++) {
            String ctx = "seed " + seed + " step " + step;
            int op = rnd.nextInt(100);
            String owner = "o" + rnd.nextInt(owners);
            Side side = rnd.nextBoolean() ? Side.BUY : Side.SELL;
            long price = 100 - priceSpan + rnd.nextInt(2 * priceSpan + 1);
            long qty = 1 + rnd.nextInt(12);
            if (op < 50) {
                long id = nextId++;
                everUsed.add(id);
                Limit l = Limit.of(id, owner, side, price, qty);
                int k = rnd.nextInt(10);
                if (k == 0) l = l.tif(Tif.IOC);
                else if (k == 1) l = l.tif(Tif.FOK);
                else if (k == 2) l = l.postOnly();
                if (rnd.nextInt(4) == 0) l = l.iceberg(1 + rnd.nextInt(4));
                Result exp = oracle.run(id, owner, side, price, qty, l.tif(), l.post(), l.display(), false);
                assertEquals(exp, book.submit(l), ctx + " submit " + l);
            } else if (op < 60) {
                long id = nextId++;
                everUsed.add(id);
                Result exp = oracle.run(id, owner, side, null, qty, Tif.IOC, false, 0, true);
                assertEquals(exp, book.market(id, owner, side, qty), ctx + " market");
            } else if (op < 72) {
                long id = everUsed.isEmpty() ? 1 : everUsed.get(rnd.nextInt(everUsed.size()));
                assertEquals(oracle.cancel(id), book.cancel(id), ctx + " cancel " + id);
            } else if (op < 85) {
                long id = everUsed.isEmpty() ? 1 : everUsed.get(rnd.nextInt(everUsed.size()));
                assertEquals(oracle.amend(id, qty), book.amendQty(id, qty), ctx + " amend " + id);
            } else {
                long id = everUsed.isEmpty() ? 1 : everUsed.get(rnd.nextInt(everUsed.size()));
                if (oracle.find(id).isPresent()) {
                    assertEquals(oracle.replace(id, price, qty), book.replace(id, price, qty), ctx + " replace " + id);
                }
            }
            book.checkInvariants();
            assertEquals(oracle.depth(Side.BUY), book.depth(Side.BUY, Integer.MAX_VALUE), ctx + " bids");
            assertEquals(oracle.depth(Side.SELL), book.depth(Side.SELL, Integer.MAX_VALUE), ctx + " asks");
            assertEquals(oracle.orders.size(), book.size(), ctx + " size");
            for (long id : everUsed) {
                var o = oracle.find(id);
                assertEquals(o.isPresent() ? java.util.OptionalLong.of(o.get().total) : java.util.OptionalLong.empty(),
                        book.leaves(id), ctx + " leaves " + id);
            }
        }
    }

    @Test
    void tightBookManyOwners() {
        for (long seed = 1; seed <= 60; seed++) runSeed(seed, 250, 4, 3);
    }

    @Test
    void fewOwnersForcesSelfTradeAndFokOwnLevel() {
        for (long seed = 100; seed < 140; seed++) runSeed(seed, 250, 2, 2);
    }

    @Test
    void wideBookRarelyCrosses() {
        for (long seed = 200; seed < 220; seed++) runSeed(seed, 300, 5, 12);
    }

    @Test
    void generatorExercisesEveryOutcome() {
        // measure the outcome mix so the differential runs are not vacuous
        int[] counts = new int[Status.values().length];
        java.util.Set<String> reasons = new java.util.TreeSet<>();
        int trades = 0;
        for (long seed = 1; seed <= 40; seed++) {
            Random rnd = new Random(seed);
            OrderBook b = new OrderBook();
            for (int i = 1; i <= 250; i++) {
                Limit l = Limit.of(i, "o" + rnd.nextInt(2), rnd.nextBoolean() ? Side.BUY : Side.SELL,
                        98 + rnd.nextInt(5), 1 + rnd.nextInt(12));
                int k = rnd.nextInt(10);
                if (k == 0) l = l.tif(Tif.IOC); else if (k == 1) l = l.tif(Tif.FOK); else if (k == 2) l = l.postOnly();
                if (rnd.nextInt(4) == 0) l = l.iceberg(1 + rnd.nextInt(4));
                Result r = b.submit(l);
                counts[r.status().ordinal()]++;
                reasons.add(r.reason());
                trades += r.trades().size();
            }
        }
        for (Status s : Status.values()) assertTrue(counts[s.ordinal()] > 100, s + " only " + counts[s.ordinal()]);
        assertTrue(reasons.containsAll(List.of("", "IOC", "FOK", "POST_ONLY", "SELF_TRADE")), reasons.toString());
        assertTrue(trades > 1000, "trades " + trades);
    }

    @Test
    void conservationOfQuantity() {
        Random rnd = new Random(7);
        OrderBook b = new OrderBook();
        long submitted = 0, tradedTaker = 0, cancelledLeaves = 0;
        for (int i = 1; i <= 2000; i++) {
            long qty = 1 + rnd.nextInt(9);
            Limit l = Limit.of(i, "o" + rnd.nextInt(3), rnd.nextBoolean() ? Side.BUY : Side.SELL, 99 + rnd.nextInt(3), qty);
            Result r = b.submit(l);
            submitted += qty;
            long sum = r.trades().stream().mapToLong(Trade::qty).sum();
            assertEquals(sum, r.filled());
            assertEquals(qty, r.filled() + r.leaves());
            tradedTaker += sum;
            if (r.status() == Status.CANCELLED) cancelledLeaves += r.leaves();
            if (r.status() == Status.REJECTED) cancelledLeaves += r.leaves();
        }
        long resting = 0;
        for (int i = 1; i <= 2000; i++) resting += b.leaves(i).orElse(0);
        // each submitted unit: filled as taker, cancelled/rejected, or rested; a rested unit later traded as maker
        // is no longer in `resting`, and maker-side units traded == taker-side units traded.
        assertEquals(submitted, 2 * tradedTaker + cancelledLeaves + resting);
    }
}

package ae.book;

import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import java.util.NoSuchElementException;
import java.util.OptionalLong;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/** Hand-derived literal cases, one per rule of TASK.md. */
class OrderBookTest {
    private OrderBook book;

    @BeforeEach
    void setUp() {
        book = new OrderBook();
    }

    private static Limit sell(long id, String owner, long price, long qty) {
        return Limit.of(id, owner, Side.SELL, price, qty);
    }

    private static Limit buy(long id, String owner, long price, long qty) {
        return Limit.of(id, owner, Side.BUY, price, qty);
    }

    @Test
    void fifoInsideLevelAndTradeAtMakerPrice() {
        book.submit(sell(1, "a", 100, 5));
        book.submit(sell(2, "b", 100, 5));
        book.submit(sell(3, "c", 99, 4));
        Result r = book.submit(buy(10, "z", 105, 12));
        // best price first (99 -> id 3), then FIFO at 100 (id 1 then id 2 partially: 4+5+3)
        assertEquals(List.of(new Trade(10, 3, 99, 4), new Trade(10, 1, 100, 5), new Trade(10, 2, 100, 3)), r.trades());
        assertEquals(Status.FILLED, r.status());
        assertEquals(12, r.filled());
        assertEquals(0, r.leaves());
        assertEquals(OptionalLong.of(2), book.leaves(2));
        assertEquals(OptionalLong.empty(), book.leaves(1));
        assertEquals(List.of(new Level(100, 2, 1)), book.depth(Side.SELL, 5));
    }

    @Test
    void partialFillRestsRemainder() {
        book.submit(sell(1, "a", 100, 4));
        Result r = book.submit(buy(2, "b", 101, 10));
        assertEquals(List.of(new Trade(2, 1, 100, 4)), r.trades());
        assertEquals(Status.RESTING, r.status());
        assertEquals(4, r.filled());
        assertEquals(6, r.leaves());
        assertEquals(OptionalLong.of(101), book.bestBid());
        assertEquals(OptionalLong.empty(), book.bestAsk());
        assertEquals(List.of(new Level(101, 6, 1)), book.depth(Side.BUY, 3));
    }

    @Test
    void nonCrossingOrderRestsWithoutTrades() {
        book.submit(sell(1, "a", 100, 4));
        Result r = book.submit(buy(2, "b", 99, 3));
        assertEquals(Status.RESTING, r.status());
        assertTrue(r.trades().isEmpty());
        assertEquals(OptionalLong.of(99), book.bestBid());
        assertEquals(OptionalLong.of(100), book.bestAsk());
    }

    @Test
    void marketSweepsLevelsAndCancelsRemainder() {
        book.submit(sell(1, "a", 100, 3));
        book.submit(sell(2, "a", 102, 3));
        Result r = book.market(9, "z", Side.BUY, 10);
        assertEquals(List.of(new Trade(9, 1, 100, 3), new Trade(9, 2, 102, 3)), r.trades());
        assertEquals(Status.CANCELLED, r.status());
        assertEquals("MARKET", r.reason());
        assertEquals(6, r.filled());
        assertEquals(4, r.leaves());
        assertEquals(0, book.size());
    }

    @Test
    void marketOnEmptyBookIsCancelledWithNoTrades() {
        Result r = book.market(1, "z", Side.SELL, 5);
        assertEquals(new Result(Status.CANCELLED, List.of(), 0, 5, "MARKET"), r);
    }

    @Test
    void iocPartialFillCancelsRemainderAndNeverRests() {
        book.submit(sell(1, "a", 100, 4));
        Result r = book.submit(buy(2, "b", 100, 10).tif(Tif.IOC));
        assertEquals(new Result(Status.CANCELLED, List.of(new Trade(2, 1, 100, 4)), 4, 6, "IOC"), r);
        assertEquals(OptionalLong.empty(), book.bestBid());
        assertEquals(OptionalLong.empty(), book.leaves(2));
    }

    @Test
    void iocFullFillIsFilled() {
        book.submit(sell(1, "a", 100, 4));
        Result r = book.submit(buy(2, "b", 100, 4).tif(Tif.IOC));
        assertEquals(Status.FILLED, r.status());
        assertEquals("", r.reason());
    }

    @Test
    void fokFillsWhenEnoughLiquidityAcrossLevels() {
        book.submit(sell(1, "a", 100, 3));
        book.submit(sell(2, "a", 101, 3));
        Result r = book.submit(buy(3, "b", 101, 5).tif(Tif.FOK));
        assertEquals(Status.FILLED, r.status());
        assertEquals(List.of(new Trade(3, 1, 100, 3), new Trade(3, 2, 101, 2)), r.trades());
    }

    @Test
    void fokRejectedLeavesBookUntouched() {
        book.submit(sell(1, "a", 100, 3));
        book.submit(sell(2, "a", 102, 3)); // beyond the limit price: must not count
        Result r = book.submit(buy(3, "b", 101, 4).tif(Tif.FOK));
        assertEquals(new Result(Status.REJECTED, List.of(), 0, 4, "FOK"), r);
        assertEquals(List.of(new Level(100, 3, 1)), book.depth(Side.SELL, 1));
        assertEquals(OptionalLong.empty(), book.leaves(3));
        assertEquals(OptionalLong.empty(), book.bestBid());
    }

    @Test
    void fokCountsHiddenIcebergQuantity() {
        book.submit(sell(1, "a", 100, 10).iceberg(2));
        Result r = book.submit(buy(2, "b", 100, 10).tif(Tif.FOK));
        assertEquals(Status.FILLED, r.status());
        assertEquals(10, r.filled());
        // slices of 2 at the same level: five trades of 2
        assertEquals(5, r.trades().size());
    }

    @Test
    void fokStopsAtLevelHoldingOwnOrderUnlessAlreadySatisfied() {
        book.submit(sell(1, "a", 100, 3));
        book.submit(sell(2, "me", 101, 5));
        // 3 available before the own level: 4 needed -> rejected although 8 is crossing
        Result r1 = book.submit(buy(3, "me", 101, 4).tif(Tif.FOK));
        assertEquals(new Result(Status.REJECTED, List.of(), 0, 4, "FOK"), r1);
        // control: only 3 needed, satisfied before the own level
        Result r2 = book.submit(buy(4, "me", 101, 3).tif(Tif.FOK));
        assertEquals(Status.FILLED, r2.status());
        assertEquals(OptionalLong.of(5), book.leaves(2));
    }

    @Test
    void postOnlyRejectedWhenItWouldCross() {
        book.submit(sell(1, "a", 100, 3));
        Result r = book.submit(buy(2, "b", 100, 3).postOnly());
        assertEquals(new Result(Status.REJECTED, List.of(), 0, 3, "POST_ONLY"), r);
        assertEquals(OptionalLong.of(3), book.leaves(1));
        assertEquals(OptionalLong.empty(), book.leaves(2));
    }

    @Test
    void postOnlyRestsOneTickAwayFromCrossing() {
        book.submit(sell(1, "a", 100, 3));
        Result r = book.submit(buy(2, "b", 99, 3).postOnly());
        assertEquals(Status.RESTING, r.status());
        assertEquals(OptionalLong.of(99), book.bestBid());
    }

    @Test
    void selfTradeStopsMatchingAfterEarlierTrades() {
        book.submit(sell(1, "other", 100, 2));
        book.submit(sell(2, "me", 100, 5));
        book.submit(sell(3, "other", 100, 4));
        Result r = book.submit(buy(4, "me", 100, 9));
        assertEquals(new Result(Status.CANCELLED, List.of(new Trade(4, 1, 100, 2)), 2, 7, "SELF_TRADE"), r);
        // own maker untouched, order behind it untouched, taker not resting
        assertEquals(OptionalLong.of(5), book.leaves(2));
        assertEquals(OptionalLong.of(4), book.leaves(3));
        assertEquals(OptionalLong.empty(), book.leaves(4));
        assertEquals(OptionalLong.empty(), book.bestBid());
    }

    @Test
    void selfTradeOnlyWhenOwnOrderIsNextNotWhenBehind() {
        book.submit(sell(1, "other", 100, 5));
        book.submit(sell(2, "me", 100, 5));
        Result r = book.submit(buy(3, "me", 100, 5));
        assertEquals(Status.FILLED, r.status());
        assertEquals(List.of(new Trade(3, 1, 100, 5)), r.trades());
    }

    @Test
    void icebergReloadsToBackOfQueue() {
        book.submit(sell(1, "a", 100, 10).iceberg(3));
        book.submit(sell(2, "b", 100, 5));
        Result r = book.submit(buy(3, "z", 100, 12).tif(Tif.IOC));
        // queue [1(vis3,tot10), 2(5)] -> 1:3 (reload, to back) -> 2:5 -> 1:3 (reload) -> 1:1
        assertEquals(List.of(new Trade(3, 1, 100, 3), new Trade(3, 2, 100, 5),
                new Trade(3, 1, 100, 3), new Trade(3, 1, 100, 1)), r.trades());
        assertEquals(Status.FILLED, r.status());
        assertEquals(OptionalLong.of(3), book.leaves(1));
        assertEquals(List.of(new Level(100, 2, 1)), book.depth(Side.SELL, 1)); // visible slice 3-1
    }

    @Test
    void depthShowsOnlyVisibleQuantityAndOrderCount() {
        book.submit(buy(1, "a", 100, 10).iceberg(4));
        book.submit(buy(2, "b", 100, 3));
        book.submit(buy(3, "c", 99, 7));
        assertEquals(List.of(new Level(100, 7, 2), new Level(99, 7, 1)), book.depth(Side.BUY, 5));
        assertEquals(List.of(new Level(100, 7, 2)), book.depth(Side.BUY, 1));
        assertEquals(List.of(), book.depth(Side.SELL, 5));
    }

    @Test
    void restingIcebergTakerShowsOnlyDisplaySlice() {
        book.submit(sell(1, "a", 100, 2));
        Result r = book.submit(buy(2, "b", 100, 9).iceberg(3));
        assertEquals(Status.RESTING, r.status());
        assertEquals(7, r.leaves());
        assertEquals(List.of(new Level(100, 3, 1)), book.depth(Side.BUY, 1));
        assertEquals(OptionalLong.of(7), book.leaves(2));
    }

    @Test
    void cancelRemovesOrderAndEmptyLevel() {
        book.submit(buy(1, "a", 100, 1));
        book.submit(buy(2, "a", 99, 1));
        assertTrue(book.cancel(1));
        assertFalse(book.cancel(1));
        assertEquals(OptionalLong.of(99), book.bestBid());
        assertFalse(book.cancel(77));
        assertEquals(1, book.size());
    }

    @Test
    void amendDownKeepsPriorityAmendUpLosesIt() {
        book.submit(sell(1, "a", 100, 5));
        book.submit(sell(2, "b", 100, 5));
        assertTrue(book.amendQty(1, 3)); // reduce: still first
        Result r1 = book.submit(buy(3, "z", 100, 1));
        assertEquals(List.of(new Trade(3, 1, 100, 1)), r1.trades());
        assertTrue(book.amendQty(1, 4)); // 2 left -> 4: goes behind order 2
        Result r2 = book.submit(buy(4, "z", 100, 1));
        assertEquals(List.of(new Trade(4, 2, 100, 1)), r2.trades());
        assertTrue(book.amendQty(1, 4)); // equal: no-op, no priority change
        assertEquals(OptionalLong.of(4), book.leaves(1));
        assertFalse(book.amendQty(99, 1));
    }

    @Test
    void amendEqualDoesNotMoveOrder() {
        book.submit(sell(1, "a", 100, 5));
        book.submit(sell(2, "b", 100, 5));
        assertTrue(book.amendQty(1, 5));
        assertEquals(List.of(new Trade(3, 1, 100, 2)), book.submit(buy(3, "z", 100, 2)).trades());
    }

    @Test
    void amendUpOfIcebergResetsVisibleSlice() {
        book.submit(sell(1, "a", 100, 4).iceberg(3));
        assertEquals(List.of(new Level(100, 3, 1)), book.depth(Side.SELL, 1));
        assertTrue(book.amendQty(1, 20));
        assertEquals(List.of(new Level(100, 3, 1)), book.depth(Side.SELL, 1));
        assertTrue(book.amendQty(1, 2)); // reduce below the slice
        assertEquals(List.of(new Level(100, 2, 1)), book.depth(Side.SELL, 1));
        book.checkInvariants();
    }

    @Test
    void replaceCanCrossAndLosesPriority() {
        book.submit(sell(1, "a", 105, 5));
        book.submit(buy(2, "b", 100, 5));
        book.submit(buy(3, "c", 100, 5));
        Result same = book.replace(2, 100, 5); // same price: goes behind 3
        assertEquals(Status.RESTING, same.status());
        assertEquals(List.of(new Trade(9, 3, 100, 5)), book.submit(sell(9, "z", 100, 5)).trades());
        Result cross = book.replace(2, 105, 8);
        assertEquals(List.of(new Trade(2, 1, 105, 5)), cross.trades());
        assertEquals(3, cross.leaves());
        assertEquals(OptionalLong.of(105), book.bestBid());
        assertThrows(NoSuchElementException.class, () -> book.replace(500, 1, 1));
    }

    @Test
    void replaceKeepsIcebergDisplayAndInvalidReplaceChangesNothing() {
        book.submit(buy(1, "a", 100, 10).iceberg(2));
        assertThrows(IllegalArgumentException.class, () -> book.replace(1, 0, 5));
        assertThrows(IllegalArgumentException.class, () -> book.replace(1, 99, 0));
        assertEquals(OptionalLong.of(10), book.leaves(1));
        assertEquals(OptionalLong.of(100), book.bestBid());
        book.replace(1, 99, 6);
        assertEquals(List.of(new Level(99, 2, 1)), book.depth(Side.BUY, 1));
    }

    @Test
    void invalidInputThrowsWithoutSideEffects() {
        book.submit(buy(1, "a", 100, 5));
        assertThrows(IllegalArgumentException.class, () -> book.submit(buy(2, "a", 100, 0)));
        assertThrows(IllegalArgumentException.class, () -> book.submit(buy(2, "a", 0, 1)));
        assertThrows(IllegalArgumentException.class, () -> book.submit(buy(2, " ", 100, 1)));
        assertThrows(IllegalArgumentException.class, () -> book.submit(buy(2, "a", 100, 1).iceberg(-1)));
        assertThrows(IllegalArgumentException.class, () -> book.submit(buy(1, "b", 90, 1))); // live id
        assertThrows(IllegalArgumentException.class, () -> book.market(3, "a", Side.SELL, 0));
        assertThrows(IllegalArgumentException.class, () -> book.market(1, "a", Side.SELL, 1)); // live id
        assertThrows(NullPointerException.class, () -> book.submit(null));
        assertThrows(NullPointerException.class, () -> book.market(3, null, Side.SELL, 1));
        assertThrows(IllegalArgumentException.class, () -> book.amendQty(1, 0));
        assertEquals(1, book.size());
        assertEquals(OptionalLong.of(5), book.leaves(1));
    }

    @Test
    void idCanBeReusedAfterFillOrCancel() {
        book.submit(sell(1, "a", 100, 1));
        book.submit(buy(2, "b", 100, 1));
        assertEquals(Status.RESTING, book.submit(sell(1, "a", 100, 1)).status());
        assertTrue(book.cancel(1));
        assertEquals(Status.RESTING, book.submit(sell(1, "a", 100, 1)).status());
    }

    @Test
    void depthRejectsNegativeLevelsAndZeroReturnsEmpty() {
        book.submit(buy(1, "a", 100, 1));
        assertEquals(List.of(), book.depth(Side.BUY, 0));
        assertThrows(IllegalArgumentException.class, () -> book.depth(Side.BUY, -1));
    }

    @Test
    void sellTakerMatchesHighestBidFirst() {
        book.submit(buy(1, "a", 99, 2));
        book.submit(buy(2, "b", 101, 2));
        Result r = book.submit(sell(3, "c", 99, 3));
        assertEquals(List.of(new Trade(3, 2, 101, 2), new Trade(3, 1, 99, 1)), r.trades());
    }
